# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_liter_a import L,H
AL=L+[['晚期拉丁 litteralis → 古法语 literal → 英语 literal','与字母、文字有关的 → 照字面理解的']]
ALL=L+[['新拉丁 alliteratio','把相近开头音排在一起；词内 al- 接 ad-'],['英语 alliteration','头韵：相邻或接近词语的起始音重复']]
WB=[
E('literal','/ˈlɪtərəl/','字面的；严格按原话的；实实在在的','对方说什么，就按那些词最直接的意思理解，不另外拐到比喻上去。','接晚期拉丁 litteralis“与字母、文字有关的”，经法语等借入路线进入英语。',AL,'说 a heavy heart 时，literal meaning 会把它理解成心脏真的很重；通常的比喻义却是心情沉重。literal translation 是紧贴原文字面翻译，未必自然，也未必最能传达原意。a literal wall 则强调那里真有一堵墙。','the literal meaning；a literal translation；take something in a literal sense。','literal 说怎么理解文字；literary 说文学；literate 说读写能力。字面理解是否合适，要看说话的人有没有使用比喻。',('The literal meaning of the phrase is different from its usual meaning.','这个短语的字面意思与通常的用意不同。'),('There was a literal wall between the two gardens.','那两个花园之间真的有一堵墙。'),sources=['https://www.etymonline.com/word/literal','https://en.wiktionary.org/wiki/literal']),
E('literally','/ˈlɪtərəli/','按字面地；确实地；用于夸张加强语气','通常是在强调“这话就是原样成立”；口语中也会借这种强度，把夸张说得更有劲。','literal + -ly；从字面的理解方式，扩展出强调实际情况和夸张加强语气的用法。',H(AL,'英语 literal → literally','字面的 → 按字面地、确实地；也用于加强语气'),'The room was literally empty 是房间真的空无一物；I literally jumped out of my skin 通常只是“我吓了一大跳”，人不会真的跳出皮肤。后一种用法存在已久，但在需要精确表达时容易引起误会，要靠上下文判断。','take something literally；literally true；literally hundreds of。','literally 的基本义与 figuratively“比喻地”相对；但它也能作夸张强调词，所以不能见到 literally 就断定整句话是物理事实。',('I meant it as a joke, but he took it literally.','我本来是在开玩笑，他却按字面认真理解了。'),('The cupboard was literally empty: there was nothing inside.','柜子真的空了，里面什么也没有。'),('I literally jumped out of my skin when the balloon burst.','气球爆开时，我简直吓得魂都飞了。'),sources=['https://www.merriam-webster.com/dictionary/literally','https://en.wiktionary.org/wiki/literally']),
E('nonliteral','英 /nɒnˈlɪtərəl/；美 /nɑːnˈlɪtərəl/','非字面的；需要按比喻等方式理解的','听到“她是团队的心脏”，不要去找器官，要去理解她为什么是核心。','non-“不是” + literal。',H(AL,'英语 non- + literal → nonliteral','字面的 → 不按字面理解的'),'nonliteral meaning 可以来自比喻、习语、反话等。说 someone has cold feet，可能是在说临阵紧张，不是脚部温度低。非字面并不等于胡说，它往往把真实感受换成更容易感到的画面。','a nonliteral meaning；nonliteral language；a nonliteral interpretation。','nonliteral 是大范围名称；metaphorical 专说比喻，ironic 专说反讽或反话，不同情况不能全部叫成一种修辞。',('The teacher explained the nonliteral meaning of the expression.','老师解释了这个表达的非字面含义。'),('The poem uses nonliteral language to describe loneliness.','这首诗用非字面的语言描写孤独。'),sources=['https://en.wiktionary.org/wiki/nonliteral']),
E('literalism','/ˈlɪtərəlɪzəm/','拘守字面的理解方式；字面主义；写实倾向','解释文字时，总把手指按在原句上：字面写了什么，就坚持按什么来理解。','literal + -ism，把按字面理解变成一种方法、倾向或主张。',H(AL,'英语 literal + -ism → literalism','字面的 → 强调或坚持字面的解释方式'),'在文本讨论中，literalism 强调明确写出的内容。有时它只是某种解释原则，有时评论者用它批评忽略语境和比喻。艺术评论里也可指贴近可观察事实的写实倾向，须按具体领域理解。','strict literalism；textual literalism；criticize literalism。','literal reading 是一次具体的字面解读；literalism 更像反复采取的原则或倾向。坚持字面是否合理，要看文本类型和语境。',('His literalism made it difficult for him to appreciate the joke.','他拘泥字面的理解方式，让他很难领会这个笑话。'),('The essay examines the limits of literalism in translation.','这篇文章讨论了翻译中拘守字面的局限。'),sources=['https://www.merriam-webster.com/dictionary/literalism','https://en.wiktionary.org/wiki/literalism']),
E('literalist','/ˈlɪtərəlɪst/','坚持字面解释的人；字面主义者','碰到一段话，倾向于先守住原文直接写明的意思的人。','literal + -ist“持某种立场或采取某种方法的人”。',H(AL,'英语 literal + -ist → literalist','字面的 → 坚持字面解释的人'),'a literalist 在文本讨论中可能反对随意补入原文没有的意思，也可能被批评过于死板。词本身不能决定哪一方正确。它还可作修饰语，说 literalist interpretation“字面主义式解释”。','a strict literalist；a literalist reading；a literalist approach。','literalist 说采取这种方式的人或立场；literalism 是这种方式本身。不要把这个词理解成“文学家”。',('A strict literalist might miss the irony in that sentence.','严格拘守字面的人可能会漏掉那句话里的反讽。'),('The two critics disagreed over the literalist reading of the poem.','两位评论者对那首诗的字面主义解读意见不一。'),sources=['https://www.merriam-webster.com/dictionary/literalism','https://en.wiktionary.org/wiki/literalist']),
E('literalistic','/ˌlɪtərəˈlɪstɪk/','字面主义式的；过于拘守字面的','已经到了需要听出话外意思的时候，解释却还紧紧卡在表面字句上。','literalist + -ic，表示这种解释倾向的性质。',H(AL,'英语 literalist → literalistic','字面主义者 → 带有字面主义倾向的'),'literalistic approach 经常带有评论色彩，批评把修辞、语境或文体压平。但有的专业讨论只是拿它命名一种解释路线，不能一律翻成“错误的”。它比 literal 更突出一种坚持字面的做法。','a literalistic interpretation；a literalistic approach。','literal 可以中性地表示字面意义；literalistic 往往进一步评价解读方式过于拘泥字面。',('A literalistic interpretation would turn the metaphor into a factual claim.','过于拘泥字面的解读，会把这个比喻当成事实陈述。'),('The reviewer thought the adaptation was too literalistic.','评论者觉得这次改编过于拘守原文的表面字句。'),sources=['https://www.merriam-webster.com/dictionary/literalism','https://en.wiktionary.org/wiki/literalistic']),
E('literalize','/ˈlɪtərəlaɪz/','按字面解释；把比喻变成实际呈现的画面','原本只是“时间飞逝”一句比喻，画家却真的画出长翅膀的钟。','literal + -ize“使成为、按某种方式处理”。',H(AL,'英语 literal + -ize → literalize','字面的 → 使字面化、按字面理解'),'literalize a metaphor 可以是在误读比喻，也可以是艺术创作故意把比喻拍成、画成真的。关键是把原本要绕一层理解的说法，改成直接看得见的事物或按表面意思理解。','literalize a metaphor；literalize an expression。','literalize 强调处理成字面意义；illustrate 只说用图或例子说明，不要求把比喻真的演出来。',('The cartoon literalizes the phrase by giving the clock wings.','漫画给钟画上翅膀，把那个说法按字面表现出来。'),('Do not literalize a figure of speech without considering the context.','不要不看语境就把修辞表达当成字面事实。'),sources=['https://www.collinsdictionary.com/dictionary/english/literalize','https://en.wiktionary.org/wiki/literalize']),
E('literalization','/ˌlɪtərəlaɪˈzeɪʃən/','字面化；把比喻变成直接画面或字面解释的过程','把“肩上有重担”画成肩头真的压着巨石，这个转化过程就是字面化。','literal 对应的 -ization 名词形式，与动词 literalize 相配。',H(AL,'英语 literalize／literal + -ization → literalization','使字面化 → 字面化的过程或结果'),'文学、电影或美术讨论中的 literalization，常是在解释一种表现手法：让抽象说法拥有实物、动作或情节。也可批评本应比喻理解的话被当真。先辨清作者是在创作画面，还是读者误读了文本。','the literalization of a metaphor；a visual literalization。','literalization 是一次转化过程；literalism 是坚持字面的解释倾向，两者有关，但不完全是同一件事。',('The giant stone is a literalization of the character’s burden.','那块巨石把角色心中的重负变成了看得见的实物。'),('The essay studies the literalization of common expressions in cartoons.','这篇文章研究漫画如何把常见表达按字面画出来。'),sources=['https://www.collinsdictionary.com/dictionary/english/literalize','https://en.wiktionary.org/wiki/literalization']),
E('literality','/ˌlɪtəˈræləti/','字面性；按字面解释的性质或程度〔较少见〕','问一段译文“有多紧贴原句的字面”，是在讨论它的字面性。','literal + -ity；重音移到 /ræ/ 所在的音节。',H(AL,'英语 literal + -ity → literality','字面的 → 字面性、字面解释'),'literality 常见于解释、翻译或文学讨论。它可说坚持原文字面的程度，也可指一种字面意思或解释。它不自动表示质量高：有时紧贴字面能保存细节，有时会损失习语真正的意思。','the literality of a translation；strict literality。','literality 与 literalness 意思接近；literalism 更突出一种原则或倾向，不只是某段文字的性质。',('The translator sacrificed some literality to preserve the humour.','译者放弃了一部分字面上的贴合，以保住幽默效果。'),('The discussion focused on the literality of the final sentence.','讨论集中在最后一句到底应当多大程度按字面理解。'),sources=['https://www.collinsdictionary.com/dictionary/english/literality','https://en.wiktionary.org/wiki/literality']),
E('alliteration','/əˌlɪtəˈreɪʃən/','头韵；相近词语开头音的重复','几个词一开口就发出相同的声音，像脚步连续踩在同一个节拍上。','借自新拉丁 alliteratio，接 ad-“靠近”与 littera“字母”；现代修辞判断重点在声音。',ALL,'wild winds 开头反复出现 /w/，便形成明显头韵。拼写相同未必算：city 与 cat 虽都用 c，开头音却是 /s/ 和 /k/。头韵常使标题、广告或诗句更醒目，但堆得太满也会显得刻意。','use alliteration；an example of alliteration；alliteration in a poem。','alliteration 主要看开头音的呼应；rhyme 常看词尾声音的呼应。英语动词 alliterate 后来才由 alliteration 逆构形成。',('The phrase “wild winds” is a simple example of alliteration.','wild winds 是一个简单的头韵例子。'),('The writer used alliteration to make the title memorable.','作者用头韵让标题更容易记住。'),sources=['https://www.etymonline.com/word/alliteration','https://en.wiktionary.org/wiki/alliteration']),
E('alliterate','/əˈlɪtəreɪt/','押头韵；使用头韵','让附近的词在开头发出彼此呼应的声音。','英语从 alliteration 逆构出 alliterate：先有这个名词，再按熟悉的词尾关系造出动词。',H(ALL,'英语 alliteration → alliterate','头韵 → 押头韵、使用头韵'),'两个词可以 alliterate，也可以说作者 alliterates“使用头韵”。比如 silver 与 sea 的开头都是 /s/。这里的 -ate 是动词尾，读 /eɪt/，与形容词 literate 的 /ət/ 不同。','words that alliterate；alliterate with；alliterate deliberately。','alliterate 是押头韵；iterate 是反复执行、迭代，来自另一条词源，不能看着相似就归为“反复字母”。',('“Silver” alliterates with “sea.”','silver 与 sea 押头韵。'),('The poet alliterates in the opening line.','诗人在开篇那一行使用了头韵。'),sources=['https://www.etymonline.com/word/alliterate','https://www.collinsdictionary.com/us/dictionary/english/alliterate']),
E('alliterative','/əˈlɪtərətɪv/','使用头韵的；有头韵特点的','一句话的开头音不断呼应，听起来有连续敲击般的节奏。','接 alliteration 的词干与形容词后缀；英语 alliterative 的记录早于动词 alliterate，不宜把后者画成它唯一的历史起点。',H(ALL,'英语 alliteration → alliterative','头韵 → 使用头韵的'),'an alliterative title 是押头韵的标题；alliterative verse 是把头韵作为重要组织手段的诗体。知道这个词后，读标题可以先听几个关键词的起始音，而不是只盯着重复字母。','an alliterative phrase；an alliterative title；alliterative verse。','alliterative 是形容词，alliteration 是名词；它不等于所有形式的押韵。',('They chose the alliterative title “Silent Streets.”','他们选用了押头韵的标题 Silent Streets。'),('The lesson introduces students to alliterative verse.','这节课向学生介绍头韵诗。'),sources=['https://www.merriam-webster.com/dictionary/alliterative','https://www.etymonline.com/word/alliterative']),
E('alliteratively','/əˈlɪtərətɪvli/','以头韵方式；用重复起始音的方式','描述怎么起标题、怎么写一句话：让前面的声音连续呼应起来。','alliterative + -ly，修饰命名、写作等动作。',H(ALL,'英语 alliterative → alliteratively','有头韵的 → 以头韵方式'),'alliteratively named 是说名称靠相同的开头音串起来。这个副词常见于对文字风格的讨论，本身并不表示写得好；头韵只是作者可以选用的一种声音效果。','alliteratively named；describe something alliteratively。','alliteratively 说采用头韵的方式；alliterative 直接修饰名词，如 an alliterative name。',('The shop was alliteratively named “Paper Palace.”','这家店用头韵取名为 Paper Palace。'),('She described the weather alliteratively as “wild, wet winds.”','她用 wild, wet winds 这个头韵表达描写天气。'),sources=['https://www.merriam-webster.com/dictionary/alliterative']),
]
